### Updated `SingleInputGateFactory`

Changes made to pass and handle `SubpartitionIndexSet` instead of a simple `IndexRange`:

```java
private static int calculateNumChannels(
        int numShuffleDescriptors, SubpartitionIndexSet subpartitionIndexSet) {
    return MathUtils.checkedDownCast(
            ((long) numShuffleDescriptors) * subpartitionIndexSet.size());
}

private void createInputChannelsAndTieredStorageService(
        String owningTaskName,
        InputGateDeploymentDescriptor inputGateDeploymentDescriptor,
        SingleInputGate inputGate,
        SubpartitionIndexSet subpartitionIndexSet,
        GateBuffersSpec gateBuffersSpec,
        InputChannelMetrics metrics) {

    ShuffleDescriptor[] shuffleDescriptors =
            inputGateDeploymentDescriptor.getShuffleDescriptors();

    // Create the input channels. There is one input channel for each consumed subpartition.
    InputChannel[] inputChannels =
            new InputChannel[calculateNumChannels(shuffleDescriptors.length, subpartitionIndexSet)];

    ChannelStatistics channelStatistics = new ChannelStatistics();

    int channelIdx = 0;
    final List<TieredStorageConsumerSpec> tieredStorageConsumerSpecs = new ArrayList<>();
    for (ShuffleDescriptor descriptor : shuffleDescriptors) {
        TieredStoragePartitionId partitionId =
                TieredStorageIdMappingUtils.convertId(descriptor.getResultPartitionID());
        for (int subpartitionIndex = subpartitionIndexSet.getStartIndex();
                subpartitionIndex <= subpartitionIndexSet.getEndIndex();
                ++subpartitionIndex) {
            inputChannels[channelIdx] =
                    createInputChannel(
                            inputGate,
                            channelIdx,
                            gateBuffersSpec.getEffectiveExclusiveBuffersPerChannel(),
                            descriptor,
                            subpartitionIndex,
                            channelStatistics,
                            metrics);
            if (tieredStorageConfiguration != null) {
                tieredStorageConsumerSpecs.add(
                        new TieredStorageConsumerSpec(
                                partitionId,
                                new TieredStorageInputChannelId(channelIdx),
                                new TieredStorageSubpartitionId(subpartitionIndex)));
            }
            channelIdx++;
        }
    }

    inputGate.setInputChannels(inputChannels);

    if (tieredStorageConfiguration != null) {
        TieredStorageConsumerClient tieredStorageConsumerClient =
                new TieredStorageConsumerClient(
                        tieredStorageConfiguration.getTierFactories(), tieredStorageConsumerSpecs, tieredStorageNettyService);
        inputGate.setTieredStorageService(
                tieredStorageConsumerSpecs, tieredStorageConsumerClient, tieredStorageNettyService);
    }

    LOG.debug(
            "{}: Created {} input channels ({}).",
            owningTaskName,
            inputChannels.length,
            channelStatistics);
}
