Here’s the refactored `OmfRecord` class:

```java
package ghidra.app.util.bin.format.omf;

import java.io.IOException;
import ghidra.app.util.bin.BinaryReader;
import ghidra.program.model.data.*;
import ghidra.util.exception.DuplicateNameException;

public abstract class OmfRecord implements StructConverter {
    protected static final String CATEGORY_PATH = "/OMF";

    protected byte recordType;
    protected int recordLength;
    protected long recordOffset;
    protected byte checkSum;

    public byte getRecordType() {
        return recordType;
    }

    public int getRecordLength() {
        return recordLength;
    }

    public long getRecordOffset() {
        return recordOffset;
    }

    public void readRecordHeader(BinaryReader reader) throws IOException {
        recordOffset = reader.getPointerIndex();
        recordType = reader.readNextByte();
        recordLength = reader.readNextShort() & 0xffff;
    }

    public void readCheckSumByte(BinaryReader reader) throws IOException {
        checkSum = reader.readNextByte();
    }

    public boolean hasBigFields() {
        return ((recordType & 1) != 0);
    }

    public boolean validCheckSum(BinaryReader reader) throws IOException {
        if (checkSum == 0) {
            return true; // Some compilers just set this to zero
        }
        return (OmfUtils.calcCheckSum(reader, recordLength) == 0);
    }

    @Override
    public String toString() {
        return String.format("name: %s, type: 0x%x, offset: 0x%x, length: 0x%x",
            OmfUtils.getRecordName(recordType & (byte) 0xfe), recordType, recordOffset, recordLength);
    }

    @Override
    public DataType toDataType() throws DuplicateNameException, IOException {
        StructureDataType struct = new StructureDataType(OmfUtils.getRecordName(getRecordType()), 0);
        struct.add(BYTE, "type", null);
        struct.add(WORD, "length", null);
        struct.add(new ArrayDataType(BYTE, getRecordLength() - 1, 1), "contents", null);
        struct.add(BYTE, "checksum", null);

        struct.setCategoryPath(new CategoryPath(CATEGORY_PATH));
        return struct;
    }
}
```

---

### 4. **Future Enhancements**

1. **Use Factory Pattern**:
    - Consider using a `OmfRecordFactory` to cleanly instantiate different `OmfRecord` types, rather than managing these in a large `switch` block.

2. **Testing**:
    - Add unit tests for `OmfUtils` to test the utility methods independently.

This refactoring approach simplifies `OmfRecord` while making the codebase more modular and easier to maintain.

To refactor the code and rename `remote` to `untrusted` as requested, you will need to adjust variable names, method names, constants, and comments accordingly to reflect the new terminology. Below is the updated and refactored code:

### Refactored Code:

```java
package ghidra.app.plugin.core.analysis;

import java.io.File;

import ghidra.app.services.*;
import ghidra.app.util.bin.format.pdb.PdbException;
import ghidra.app.util.bin.format.pdb.PdbParser;
import ghidra.app.util.importer.MessageLog;
import ghidra.framework.options.Options;
import ghidra.program.model.address.AddressSetView;
import ghidra.program.model.listing.Program;
import ghidra.util.Msg;
import ghidra.util.exception.CancelledException;
import ghidra.util.task.TaskMonitor;

/**
 * Finds and applies PDB debug information to the given Windows executable.
 */
public class PdbAnalyzer extends AbstractAnalyzer {
	static final String NAME = "PDB MSDIA";
	static final boolean DEFAULT_ENABLEMENT = !PdbUniversalAnalyzer.DEFAULT_ENABLEMENT;
	private static final String DESCRIPTION =
		"PDB Analyzer.\n" +
			"Requires MS DIA-SDK for raw PDB processing (Windows only).\n" +
			"Also supports pre-processed XML files.\n" +
			"PDB Symbol Server searching is configured in Edit -> Symbol Server Config.\n";

	private static final String ERROR_TITLE = "Error in PDB Analyzer";

	private boolean searchUntrustedLocations = false;

	// only try once per transaction due to extensive error logging which may get duplicated
	private long lastTransactionId = -1;

	//==============================================================================================
	public PdbAnalyzer() {
		super(NAME, DESCRIPTION, AnalyzerType.BYTE_ANALYZER);
		setDefaultEnablement(DEFAULT_ENABLEMENT);
		setPriority(AnalysisPriority.FORMAT_ANALYSIS.after());
		setSupportsOneTimeAnalysis();
	}

	@Override
	public boolean added(Program program, AddressSetView set, TaskMonitor monitor, MessageLog log) {

		// Only run once per transaction - avoid message duplication
		long txId = program.getCurrentTransactionInfo().getID();
		if (txId == lastTransactionId) {
			return false;
		}
		lastTransactionId = txId;

		// Only run if restricted set corresponds to entire program
		if (!set.contains(program.getMemory())) {
			return false;
		}

		if (PdbParser.isAlreadyLoaded(program)) {
			if (!PdbUniversalAnalyzer.isEnabled(program)) { // yield to other analyzer complaining
				Msg.info(this, "Skipping PDB analysis since it has previously run.");
				Msg.info(this, ">> Clear 'PDB Loaded' program property or use Load PDB action if " +
					"additional PDB processing required.");
			}
			return true;
		}

		if (PdbUniversalAnalyzer.isEnabled(program)) {
			log.appendMsg(getName(),
				"Stopped: Cannot run with " + PdbUniversalAnalyzer.NAME + " Analyzer enabled");
			return false;
		}

		File pdbFile = PdbAnalyzerCommon.findPdb(this, program, searchUntrustedLocations, monitor);
		if (pdbFile == null) {
			// warnings have already been logged
			return false;
		}

		AutoAnalysisManager mgr = AutoAnalysisManager.getAnalysisManager(program);
		return parsePdb(pdbFile, program, mgr, monitor, log);
	}

	boolean parsePdb(File pdb, Program program, AutoAnalysisManager mgr, TaskMonitor monitor,
			MessageLog log) {
		DataTypeManagerService dataTypeManagerService = mgr.getDataTypeManagerService();
		PdbParser parser =
			new PdbParser(pdb, program, dataTypeManagerService, true, false, monitor);

		String message;

		try {
			parser.parse();
			parser.openDataTypeArchives();
			parser.applyTo(log);
			return true;
		}
		catch (PdbException e) {
			message = e.getMessage();
			log.appendMsg(getName(), message);
			log.setStatus(message);
			return false;
		}
		catch (CancelledException e) {
			return false;
		}
		catch (Exception e) {
			String msg = e.getMessage();
			if (msg == null) {
				msg = e.toString();
			}
			Msg.showError(this, null, ERROR_TITLE, msg, e);
			return false;
		}

	}

